<?php use SPFPU\Core\{Csrf,View}; ?>
<header class="page-head"><div><p class="eyebrow">Pentadbiran</p><h1>Pengurusan Pengguna</h1><p>Akaun dinyahaktif kekal dalam rekod bagi memelihara sejarah dan pengarang.</p></div><button class="button primary" data-dialog-open="pengguna-baru">Tambah pengguna</button></header>
<div class="table-wrap"><table><thead><tr><th>Nama Penuh</th><th>Username</th><th>E-mel</th><th>No. Phone</th><th>Role</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td data-label="Nama Penuh"><strong><?=View::e($u['fullname'])?></strong><?php if($u['reset_warning']):?><small class="warning-text">Kata laluan sementara</small><?php endif?></td><td data-label="Username"><?=View::e($u['username'])?></td><td data-label="E-mel"><?=View::e($u['email'])?></td><td data-label="No. Phone"><?=View::e($u['phone']?:'—')?></td><td data-label="Role"><?=View::e($u['role'])?></td><td data-label="Status"><span class="status <?=$u['status']==='Active'?'open':'closed'?>"><?=View::e($u['status']==='Active'?'Aktif':'Tidak aktif')?></span></td><td><button class="row-menu" data-dialog-open="user-<?=(int)$u['id']?>">Urus</button></td></tr><dialog id="user-<?=(int)$u['id']?>"><form method="post" action="/admin/pengguna/<?=(int)$u['id']?>" class="dialog-form"><?=Csrf::field()?><h2>Urus <?=View::e($u['fullname'])?></h2><p><?=View::e($u['role'])?> · <?=View::e($u['status'])?></p><?php if($u['role']==='Staff'):?><label>Nama Penuh<input name="fullname" maxlength="150" value="<?=View::e($u['fullname'])?>" required></label><div class="form-grid"><label>Username<input name="username" value="<?=View::e($u['username'])?>" required></label><label>No. Phone<input name="phone" value="<?=View::e($u['phone']??'')?>"></label></div><label>E-mel<input type="email" name="email" value="<?=View::e($u['email'])?>" required></label><button name="action" value="update" class="button primary">Simpan butiran Staff</button><?php endif?><div class="action-stack"><button name="action" value="reset" class="button quiet">Tetap semula ke Passw123</button><?php if($u['role']==='Staff'):?><button name="action" value="promote" class="button quiet">Jadikan Admin</button><?php else:?><button name="action" value="demote" class="button quiet">Jadikan Staff</button><?php endif?><?php if($u['status']==='Active'):?><button name="action" value="deactivate" class="button danger">Nyahaktif akaun</button><?php else:?><button name="action" value="activate" class="button primary">Aktifkan akaun</button><?php endif?></div><footer><button type="button" class="button quiet" data-dialog-close>Tutup</button></footer></form></dialog><?php endforeach?></tbody></table></div>
<dialog id="pengguna-baru"><form method="post" action="/admin/pengguna" class="dialog-form"><?=Csrf::field()?><header><div><p class="eyebrow">Akaun dalaman</p><h2>Tambah pengguna</h2></div><button type="button" class="icon-button" data-dialog-close>×</button></header><label>Nama Penuh<input name="fullname" maxlength="150" required></label><div class="form-grid"><label>Username<input name="username" pattern="[A-Za-z0-9._-]{3,50}" required></label><label>Role<select name="role"><option>Staff</option><option>Admin</option></select></label></div><label>E-mel<input type="email" name="email" required></label><label>No. Phone <span>(pilihan)</span><input name="phone" maxlength="30"></label><label>Kata Laluan<input type="password" name="password" minlength="8" maxlength="19" required><small>8–19 aksara; huruf besar, kecil dan nombor.</small></label><footer><button type="button" class="button quiet" data-dialog-close>Batal</button><button class="button primary">Tambah pengguna</button></footer></form></dialog>
